const input = $json;
const models = input.models || {};
if (!models.primary) {
  throw new Error('Gemini Image gateway: models.primary is required');
}
const base = 'https://generativelanguage.googleapis.com/v1beta/models/';
const imageConfig = { aspectRatio: input.aspect_ratio || '16:9' };
if (input.image_size) {
  imageConfig.imageSize = input.image_size;
}
const body = {
  contents: [{ role: 'user', parts: [{ text: String(input.prompt || '') }] }],
  generationConfig: { responseModalities: ['IMAGE'], imageConfig }
};
const fallbackModel = models.fallback || models.primary;
// Fault injection: aim the primary call at a model id that does not exist, so the
// real API fails and the fallback path runs exactly as it would during an outage.
const primaryTarget = input.simulate_primary_fail ? models.primary + '-simulated-outage' : models.primary;
const now = Date.now();
return {
  json: {
    purpose: input.purpose || 'image',
    body,
    primary: { model: models.primary, url: base + primaryTarget + ':generateContent' },
    fallback: { model: fallbackModel, url: base + fallbackModel + ':generateContent' },
    timeout_ms: Math.min(Math.max(Number(input.timeout_ms) || 90000, 5000), 240000),
    deadline_at: Number(input.deadline_at) || now + 280000,
    pricing: input.pricing || {},
    simulated_failure: Boolean(input.simulate_primary_fail),
    started_at: now,
    passthrough: input.passthrough === undefined ? null : input.passthrough
  }
};

const ATTEMPT = 'primary';
const prep = $('Prepare Image Request').first().json;
const res = $json || {};
const zero = { input_tokens: 0, output_tokens: 0, image_tokens: 0, thinking_tokens: 0 };
const base = { attempt: ATTEMPT, model: prep[ATTEMPT].model, ok: false, finish_reason: null, usage: zero, error: null };

// HTTP failures arrive here through the node's error output, after its retry.
if (!res.candidates && res.error !== undefined) {
  const raw = res.error;
  const details = res.details || {};
  let message = typeof raw === 'string' ? raw : String((raw && raw.message) || JSON.stringify(raw));
  const description = details.description || (raw && raw.description);
  if (description && description !== message) message += ' | ' + description;
  const causeMessage = raw && raw.cause && raw.cause.message ? String(raw.cause.message) : '';
  const codeMatch = /^(\d{3})\b/.exec(causeMessage) || /^(\d{3})\b/.exec(message);
  const status = details.httpCode || (raw && raw.httpCode) || (codeMatch && codeMatch[1]) || null;
  const type = /timeout|ETIMEDOUT|ECONNABORTED/i.test(message + ' ' + causeMessage) ? 'timeout' : 'http_error';
  return { json: { ...base, error: { type, http_status: status ? Number(status) : null, message: message.slice(0, 600) } } };
}

const candidate = (res.candidates || [])[0] || {};
const parts = (candidate.content && candidate.content.parts) || [];
// Thinking image models can emit draft images marked as thoughts; keep the last final one.
const imageParts = parts.filter(p => (p.inlineData || p.inline_data) && !p.thought);
const imagePart = imageParts[imageParts.length - 1];
const finishReason = candidate.finishReason || (res.promptFeedback && res.promptFeedback.blockReason) || 'NO_CANDIDATE';
const meta = res.usageMetadata || {};
const imageTokens = (meta.candidatesTokensDetails || [])
  .filter(d => d.modality === 'IMAGE')
  .reduce((sum, d) => sum + (d.tokenCount || 0), 0);
const usage = {
  input_tokens: meta.promptTokenCount || 0,
  output_tokens: (meta.candidatesTokenCount || 0) + (meta.thoughtsTokenCount || 0),
  image_tokens: imageTokens,
  thinking_tokens: meta.thoughtsTokenCount || 0
};
const out = { ...base, finish_reason: finishReason, usage };
if (!imagePart) {
  const note = parts.filter(p => typeof p.text === 'string' && !p.thought).map(p => p.text).join(' ').slice(0, 300);
  return { json: { ...out, error: { type: 'no_image', message: 'Model returned no image (finishReason ' + finishReason + ')' + (note ? ': ' + note : '') } } };
}
const inline = imagePart.inlineData || imagePart.inline_data;
const mimeType = inline.mimeType || inline.mime_type || 'image/png';
const subtype = mimeType.split('/')[1] || 'png';
const extension = subtype === 'jpeg' ? 'jpg' : subtype;
return {
  json: { ...out, ok: true, mime_type: mimeType, file_extension: extension, bytes: Math.round(inline.data.length * 3 / 4) },
  binary: { image: { data: inline.data, mimeType, fileName: 'image.' + extension, fileExtension: extension } }
};

const prep = $('Prepare Image Request').first().json;
const finalItem = $input.first();
const final = finalItem.json;
const primary = $('Parse Primary Image').first().json;
const attempts = (final.attempt === 'fallback' ? [primary, final] : [final]).map(a => {
  const price = prep.pricing[a.model] || null;
  const u = a.usage;
  const textTokens = Math.max(0, u.output_tokens - u.image_tokens);
  const cost = price
    ? (u.input_tokens * price.input + textTokens * price.output + u.image_tokens * (price.output_image || price.output)) / 1e6
    : 0;
  return { attempt: a.attempt, model: a.model, ok: a.ok, usage: u, cost_usd: Number(cost.toFixed(6)), error: a.error };
});
const usage = { input_tokens: 0, output_tokens: 0, image_tokens: 0, thinking_tokens: 0 };
for (const a of attempts) {
  usage.input_tokens += a.usage.input_tokens;
  usage.output_tokens += a.usage.output_tokens;
  usage.image_tokens += a.usage.image_tokens;
  usage.thinking_tokens += a.usage.thinking_tokens;
}
const ok = final.ok === true;
const result = {
  json: {
    ok,
    purpose: prep.purpose,
    model: ok ? final.model : null,
    mime_type: ok ? final.mime_type : null,
    file_extension: ok ? final.file_extension : null,
    bytes: ok ? final.bytes : 0,
    fallback_used: final.attempt === 'fallback',
    finish_reason: final.finish_reason,
    latency_ms: Date.now() - prep.started_at,
    usage,
    cost_usd: Number(attempts.reduce((sum, a) => sum + a.cost_usd, 0).toFixed(6)),
    attempts,
    error: ok ? null : attempts.map(a => a.attempt + ' ' + a.model + ': ' + (a.error ? a.error.message : 'unknown error')).join(' | '),
    simulated_failure: prep.simulated_failure,
    passthrough: prep.passthrough
  }
};
if (ok && finalItem.binary) {
  result.binary = finalItem.binary;
}
return [result];

